import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const LOGIN_TYPES = ['웹', '메신저', '모바일'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function text(value: unknown): string {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
}

function intOf(value: unknown, fallback: number): number {
  const raw = text(value);
  if (raw === '') {
    return fallback;
  }
  if (!/^\d+$/.test(raw)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기는 0 이상의 정수여야 합니다.');
  }
  return Number(raw);
}

@Controller('api/v1')
export class FnSfr03802Controller {
  @Get('/access-logs/menu-usages')
  async listMenuUsageLogs(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const query = checks.queryOf(req.query);
    const accessedFrom = text(query['accessedFrom']);
    const accessedTo = text(query['accessedTo']);
    const employeeName = text(query['employeeName']);
    const menuName = text(query['menuName']);
    const loginType = text(query['loginType']);
    if (accessedFrom !== '' && !DATE_PATTERN.test(accessedFrom)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일 형식이 올바르지 않습니다. (YYYY-MM-DD)');
    }
    if (accessedTo !== '' && !DATE_PATTERN.test(accessedTo)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 종료일 형식이 올바르지 않습니다. (YYYY-MM-DD)');
    }
    if (employeeName.length > 100 || menuName.length > 100) {
      throw new ApiError(400, 'VALIDATION_FAILED', '성명과 메뉴명은 100자 이하여야 합니다.');
    }
    if (loginType !== '' && !LOGIN_TYPES.includes(loginType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '접속 환경은 웹, 메신저, 모바일 중 하나여야 합니다.');
    }
    const page = intOf(query['page'], 0);
    const size = intOf(query['size'], DEFAULT_SIZE);
    if (size < 1 || size > MAX_SIZE) {
      throw new ApiError(400, 'VALIDATION_FAILED', '크기는 1 이상 200 이하여야 합니다.');
    }
    return transaction(async (db) => {
      // 검색 조건은 모두 선택이며 입력한 조건은 AND로 적용한다.
      const where: string[] = ["a.event_type = '메뉴사용'"];
      const params: Record<string, unknown> = {};
      if (accessedFrom !== '') {
        where.push('a.accessed_at >= CAST(:accessedFrom AS date)');
        params.accessedFrom = accessedFrom;
      }
      if (accessedTo !== '') {
        where.push("a.accessed_at < CAST(:accessedTo AS date) + interval '1 day'");
        params.accessedTo = accessedTo;
      }
      if (employeeName !== '') {
        where.push("e.name LIKE '%' || :employeeName || '%'");
        params.employeeName = employeeName;
      }
      if (menuName !== '') {
        where.push("m.name LIKE '%' || :menuName || '%'");
        params.menuName = menuName;
      }
      if (loginType !== '') {
        where.push('a.login_type = :loginType');
        params.loginType = loginType;
      }
      const from =
        'FROM access_log a ' +
        'JOIN menu m ON m.menu_id = a.menu_id ' +
        'LEFT JOIN employee e ON e.employee_id = a.employee_id ' +
        'WHERE ' + where.join(' AND ');
      const countRows = await db.query('SELECT COUNT(*) AS "total" ' + from, params);
      const total = Number(countRows[0]?.total ?? 0);
      const items = await db.query(
        'SELECT e.name AS "employeeName", ' +
          'a.accessed_at AS "accessedAt", ' +
          'm.name AS "menuName", ' +
          'a.login_ip AS "loginIp", ' +
          'a.login_type AS "loginType" ' +
          from +
          ' ORDER BY a.accessed_at DESC, a.access_log_id DESC ' +
          'LIMIT :limit OFFSET :offset',
        { ...params, limit: size, offset: page * size },
      );
      return { items, page, size, total };
    });
  }
}

