import { useState } from 'react';
import {
  Band,
  DataTable,
  DateInput,
  DateText,
  ErrorText,
  Field,
  Filters,
  Num,
  Pager,
  Select,
  Text as _unused,
  TextInput,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const PAGE_SIZE = 20;

export default function FnSfr03802Page({ role, notify }: PageProps) {
  const [accessedFrom, setAccessedFrom] = useState('');
  const [accessedTo, setAccessedTo] = useState('');
  const [employeeName, setEmployeeName] = useState('');
  const [menuName, setMenuName] = useState('');
  const [loginType, setLoginType] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/access-logs/menu-usages', role, undefined, { ...applied, page, size: PAGE_SIZE }),
    [applied, page, role],
  );

  function search() {
    if (accessedFrom !== '' && accessedTo !== '' && accessedFrom > accessedTo) {
      notify('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setPage(0);
    setApplied({ accessedFrom, accessedTo, employeeName, menuName, loginType });
  }

  function reset() {
    setAccessedFrom('');
    setAccessedTo('');
    setEmployeeName('');
    setMenuName('');
    setLoginType('');
    setPage(0);
    setApplied({});
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 건수</h2>
        <Tiles items={[['메뉴 사용 내역', <Num value={data?.total ?? 0} />]]} />
      </section>
      <section className="box span-12">
        <h2>메뉴 사용 내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일">
            <DateInput value={accessedFrom} onChange={setAccessedFrom} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={accessedTo} onChange={setAccessedTo} />
          </Field>
          <Field label="성명">
            <TextInput value={employeeName} onChange={setEmployeeName} />
          </Field>
          <Field label="메뉴명">
            <TextInput value={menuName} onChange={setMenuName} />
          </Field>
          <Field label="접속 환경(웹/모바일)">
            <Select
              value={loginType}
              onChange={setLoginType}
              options={[
                ['웹', '웹'],
                ['메신저', '메신저'],
                ['모바일', '모바일'],
              ]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        {error !== '' && <ErrorText text={error} />}
        <Band total={data?.total} />
        <DataTable
          columns={[
            { key: 'employeeName', label: '성명' },
            { key: 'accessedAt', label: '접속·사용 일시', render: (row) => <DateText value={row.accessedAt} time /> },
            { key: 'menuName', label: '메뉴명' },
            { key: 'loginIp', label: '접속 IP' },
            { key: 'loginType', label: '로그인 구분' },
          ]}
          rows={data?.items ?? []}
          empty={loading ? '불러오는 중입니다.' : '조회 결과가 없습니다.'}
        />
        <Pager page={page} size={PAGE_SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
    </div>
  );
}
